import { t } from 'elysia'

export const AddUploadPartRequestSchema = t.Object(
  { data: t.File({ description: 'The chunk of bytes for this Part.\n' }) },
  { additionalProperties: false },
)

export const AdminApiKeySchema = t.Object(
  {
    object: t.Literal('organization.admin_api_key', {
      description: 'The object type, which is always `organization.admin_api_key`',
    }),
    id: t.String({
      example: 'key_abc',
      description: 'The identifier, which can be referenced in API endpoints',
    }),
    name: t.Optional(
      t.Union([t.String(), t.Null()], {
        example: 'Administration Key',
        description: 'The name of the API key',
      }),
    ),
    redacted_value: t.String({
      example: 'sk-admin...def',
      description: 'The redacted value of the API key',
    }),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      example: 1711471533,
      description: 'The Unix timestamp (in seconds) of when the API key was created',
    }),
    expires_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        example: 1714063533,
        description: 'The Unix timestamp (in seconds) of when the API key expires',
      }),
      t.Null(),
    ]),
    last_used_at: t.Optional(
      t.Union([
        t.Integer({
          format: 'unixtime',
          maximum: 9007199254740991,
          example: 1711471534,
          description: 'The Unix timestamp (in seconds) of when the API key was last used',
        }),
        t.Null(),
      ]),
    ),
    owner: t.Object({
      type: t.Optional(t.String({ example: 'user', description: 'Always `user`' })),
      object: t.Optional(
        t.String({
          example: 'organization.user',
          description: 'The object type, which is always organization.user',
        }),
      ),
      id: t.Optional(
        t.String({
          example: 'sa_456',
          description: 'The identifier, which can be referenced in API endpoints',
        }),
      ),
      name: t.Optional(
        t.String({ example: 'My Service Account', description: 'The name of the user' }),
      ),
      created_at: t.Optional(
        t.Integer({
          format: 'unixtime',
          maximum: 9007199254740991,
          example: 1711471533,
          description: 'The Unix timestamp (in seconds) of when the user was created',
        }),
      ),
      role: t.Optional(t.String({ example: 'owner', description: 'Always `owner`' })),
    }),
  },
  { description: 'Represents an individual Admin API key in an org.' },
)

export const AdminApiKeyCreateResponseSchema = t.Intersect([
  AdminApiKeySchema,
  t.Object(
    {
      value: t.String({
        example: 'sk-admin-1234abcd',
        description: 'The value of the API key. Only shown on create.',
      }),
    },
    {
      description:
        'The newly created admin API key. The `value` field is only returned once, when the key is created.',
    },
  ),
])

export const ApiKeyListSchema = t.Object({
  object: t.Literal('list', { example: 'list' }),
  data: t.Array(AdminApiKeySchema),
  has_more: t.Boolean({ example: false }),
  first_id: t.Optional(t.Union([t.String(), t.Null()], { example: 'key_abc' })),
  last_id: t.Optional(t.Union([t.String(), t.Null()], { example: 'key_xyz' })),
})

export const AssignedRoleDetailsSchema = t.Object(
  {
    id: t.String({ description: 'Identifier for the role.' }),
    name: t.String({ description: 'Name of the role.' }),
    permissions: t.Array(t.String(), { description: 'Permissions associated with the role.' }),
    resource_type: t.String({ description: 'Resource type the role applies to.' }),
    predefined_role: t.Boolean({ description: 'Whether the role is predefined by OpenAI.' }),
    description: t.Union([t.String(), t.Null()], { description: 'Description of the role.' }),
    created_at: t.Union([t.Integer({ format: 'unixtime', maximum: 9007199254740991 }), t.Null()], {
      description: 'When the role was created.',
    }),
    updated_at: t.Union([t.Integer({ format: 'unixtime', maximum: 9007199254740991 }), t.Null()], {
      description: 'When the role was last updated.',
    }),
    created_by: t.Union([t.String(), t.Null()], {
      description: 'Identifier of the actor who created the role.',
    }),
    created_by_user_obj: t.Union([t.Object({}), t.Null()], {
      description: 'User details for the actor that created the role, when available.',
    }),
    metadata: t.Union([t.Object({}), t.Null()], {
      description: 'Arbitrary metadata stored on the role.',
    }),
    assignment_sources: t.Union(
      [t.Array(t.Object({ principal_id: t.String(), principal_type: t.String() })), t.Null()],
      { description: 'Principals from which the role assignment is inherited, when available.' },
    ),
  },
  {
    description:
      'Detailed information about a role assignment entry returned when listing assignments.',
  },
)

export const AssistantToolsCodeSchema = t.Object(
  {
    type: t.Literal('code_interpreter', {
      description: 'The type of tool being defined: `code_interpreter`',
    }),
  },
  { title: 'Code interpreter tool' },
)

export const FileSearchRankerSchema = t.UnionEnum(['auto', 'default_2024_08_21'], {
  description:
    'The ranker to use for the file search. If not specified will use the `auto` ranker.',
  default: undefined,
})

export const FileSearchRankingOptionsSchema = t.Object(
  {
    ranker: t.Optional(FileSearchRankerSchema),
    score_threshold: t.Number({
      minimum: 0,
      maximum: 1,
      description:
        'The score threshold for the file search. All values must be a floating point number between 0 and 1.',
    }),
  },
  {
    title: 'File search tool call ranking options',
    description:
      'The ranking options for the file search. If not specified, the file search tool will use the `auto` ranker and a score_threshold of 0.\n\nSee the [file search tool documentation](https://developers.openai.com/api/docs/guides/tools-file-search#retrieval-customization) for more information.\n',
  },
)

export const AssistantToolsFileSearchSchema = t.Object(
  {
    type: t.Literal('file_search', {
      description: 'The type of tool being defined: `file_search`',
    }),
    file_search: t.Optional(
      t.Object(
        {
          max_num_results: t.Optional(
            t.Integer({
              minimum: 1,
              maximum: 50,
              description:
                'The maximum number of results the file search tool should output. The default is 20 for `gpt-4*` models and 5 for `gpt-3.5-turbo`. This number should be between 1 and 50 inclusive.\n\nNote that the file search tool may output fewer than `max_num_results` results. See the [file search tool documentation](https://developers.openai.com/api/docs/guides/tools-file-search#retrieval-customization) for more information.\n',
            }),
          ),
          ranking_options: t.Optional(FileSearchRankingOptionsSchema),
        },
        { description: 'Overrides for the file search tool.' },
      ),
    ),
  },
  { title: 'FileSearch tool' },
)

export const FunctionParametersSchema = t.Object(
  {},
  {
    description:
      'The parameters the functions accepts, described as a JSON Schema object. See the [guide](https://developers.openai.com/api/docs/guides/function-calling) for examples, and the [JSON Schema reference](https://json-schema.org/understanding-json-schema/) for documentation about the format.\n\nOmitting `parameters` defines a function with an empty parameter list.',
  },
)

export const FunctionObjectSchema = t.Object({
  description: t.Optional(
    t.String({
      description:
        'A description of what the function does, used by the model to choose when and how to call the function.',
    }),
  ),
  name: t.String({
    description:
      'The name of the function to be called. Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 64.',
  }),
  parameters: t.Optional(FunctionParametersSchema),
  strict: t.Optional(
    t.Union([
      t.Boolean({
        description:
          'Whether to enable strict schema adherence when generating the function call. If set to true, the model will follow the exact schema defined in the `parameters` field. Only a subset of JSON Schema is supported when `strict` is `true`. Learn more about Structured Outputs in the [function calling guide](https://developers.openai.com/api/docs/guides/function-calling).',
        default: false,
      }),
      t.Null(),
    ]),
  ),
})

export const AssistantToolsFunctionSchema = t.Object(
  {
    type: t.Literal('function', { description: 'The type of tool being defined: `function`' }),
    function: FunctionObjectSchema,
  },
  { title: 'Function tool' },
)

export const MetadataSchema = t.Union([
  t.Record(t.String(), t.String(), {
    description:
      'Set of 16 key-value pairs that can be attached to an object. This can be\nuseful for storing additional information about the object in a structured\nformat, and querying for objects via API or the dashboard.\n\nKeys are strings with a maximum length of 64 characters. Values are strings\nwith a maximum length of 512 characters.\n',
  }),
  t.Null(),
])

export const ResponseFormatTextSchema = t.Object(
  {
    type: t.Literal('text', {
      description: 'The type of response format being defined. Always `text`.',
    }),
  },
  { title: 'Text', description: 'Default response format. Used to generate text responses.\n' },
)

export const ResponseFormatJsonObjectSchema = t.Object(
  {
    type: t.Literal('json_object', {
      description: 'The type of response format being defined. Always `json_object`.',
    }),
  },
  {
    title: 'JSON object',
    description:
      'JSON object response format. An older method of generating JSON responses.\nUsing `json_schema` is recommended for models that support it. Note that the\nmodel will not generate JSON without a system or user message instructing it\nto do so.\n',
  },
)

export const ResponseFormatJsonSchemaSchemaSchema = t.Object(
  {},
  {
    title: 'JSON schema',
    description:
      'The schema for the response format, described as a JSON Schema object.\nLearn how to build JSON schemas [here](https://json-schema.org/).\n',
  },
)

export const ResponseFormatJsonSchemaSchema = t.Object(
  {
    type: t.Literal('json_schema', {
      description: 'The type of response format being defined. Always `json_schema`.',
    }),
    json_schema: t.Object(
      {
        description: t.Optional(
          t.String({
            description:
              'A description of what the response format is for, used by the model to\ndetermine how to respond in the format.\n',
          }),
        ),
        name: t.String({
          description:
            'The name of the response format. Must be a-z, A-Z, 0-9, or contain\nunderscores and dashes, with a maximum length of 64.\n',
        }),
        schema: t.Optional(ResponseFormatJsonSchemaSchemaSchema),
        strict: t.Optional(
          t.Union([
            t.Boolean({
              description:
                'Whether to enable strict schema adherence when generating the output.\nIf set to true, the model will always follow the exact schema defined\nin the `schema` field. Only a subset of JSON Schema is supported when\n`strict` is `true`. To learn more, read the [Structured Outputs\nguide](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
              default: false,
            }),
            t.Null(),
          ]),
        ),
      },
      {
        title: 'JSON schema',
        description: 'Structured Outputs configuration options, including a JSON Schema.\n',
      },
    ),
  },
  {
    title: 'JSON schema',
    description:
      'JSON Schema response format. Used to generate structured JSON responses.\nLearn more about [Structured Outputs](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
  },
)

export const AssistantsApiResponseFormatOptionSchema = t.Union(
  [
    t.Literal('auto', { description: '`auto` is the default value\n' }),
    ResponseFormatTextSchema,
    ResponseFormatJsonObjectSchema,
    ResponseFormatJsonSchemaSchema,
  ],
  {
    description:
      'Specifies the format that the model must output. Compatible with [GPT-4o](https://developers.openai.com/api/docs/models/gpt-4o), [GPT-4 Turbo](https://developers.openai.com/api/docs/models/gpt-4-turbo), and all GPT-3.5 Turbo models since `gpt-3.5-turbo-1106`.\n\nSetting to `{ "type": "json_schema", "json_schema": {...} }` enables Structured Outputs which ensures the model will match your supplied JSON schema. Learn more in the [Structured Outputs guide](https://developers.openai.com/api/docs/guides/structured-outputs).\n\nSetting to `{ "type": "json_object" }` enables JSON mode, which ensures the message the model generates is valid JSON.\n\n**Important:** when using JSON mode, you **must** also instruct the model to produce JSON yourself via a system or user message. Without this, the model may generate an unending stream of whitespace until the generation reaches the token limit, resulting in a long-running and seemingly "stuck" request. Also note that the message content may be partially cut off if `finish_reason="length"`, which indicates the generation exceeded `max_tokens` or the conversation exceeded the max context length.\n',
  },
)

export const AssistantObjectSchema = t.Object(
  {
    id: t.String({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: t.Literal('assistant', {
      description: 'The object type, which is always `assistant`.',
    }),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) for when the assistant was created.',
    }),
    name: t.Union([
      t.String({
        maxLength: 256,
        description: 'The name of the assistant. The maximum length is 256 characters.\n',
      }),
      t.Null(),
    ]),
    description: t.Union([
      t.String({
        maxLength: 512,
        description: 'The description of the assistant. The maximum length is 512 characters.\n',
      }),
      t.Null(),
    ]),
    model: t.String({
      description:
        'ID of the model to use. You can use the [List models](https://developers.openai.com/api/reference/resources/models/methods/list) API to see all of your available models, or see our [Model overview](https://developers.openai.com/api/docs/models) for descriptions of them.\n',
    }),
    instructions: t.Union([
      t.String({
        maxLength: 256000,
        description:
          'The system instructions that the assistant uses. The maximum length is 256,000 characters.\n',
      }),
      t.Null(),
    ]),
    tools: t.Array(
      t.Union([
        AssistantToolsCodeSchema,
        AssistantToolsFileSearchSchema,
        AssistantToolsFunctionSchema,
      ]),
      {
        maxItems: 128,
        description:
          'A list of tool enabled on the assistant. There can be a maximum of 128 tools per assistant. Tools can be of types `code_interpreter`, `file_search`, or `function`.\n',
        default: [],
      },
    ),
    tool_resources: t.Optional(
      t.Union([
        t.Object(
          {
            code_interpreter: t.Optional(
              t.Object({
                file_ids: t.Optional(
                  t.Array(t.String(), {
                    maxItems: 20,
                    description:
                      'A list of [file](https://developers.openai.com/api/reference/resources/files) IDs made available to the `code_interpreter`` tool. There can be a maximum of 20 files associated with the tool.\n',
                    default: [],
                  }),
                ),
              }),
            ),
            file_search: t.Optional(
              t.Object({
                vector_store_ids: t.Optional(
                  t.Array(t.String(), {
                    maxItems: 1,
                    description:
                      'The ID of the [vector store](https://developers.openai.com/api/reference/resources/vector_stores) attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n',
                  }),
                ),
              }),
            ),
          },
          {
            description:
              "A set of resources that are used by the assistant's tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n",
          },
        ),
        t.Null(),
      ]),
    ),
    metadata: MetadataSchema,
    temperature: t.Optional(
      t.Union([
        t.Number({
          minimum: 0,
          maximum: 2,
          example: 1,
          description:
            'What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic.\n',
          default: 1,
        }),
        t.Null(),
      ]),
    ),
    top_p: t.Optional(
      t.Union([
        t.Number({
          minimum: 0,
          maximum: 1,
          example: 1,
          description:
            'An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.\n\nWe generally recommend altering this or temperature but not both.\n',
          default: 1,
        }),
        t.Null(),
      ]),
    ),
    response_format: t.Optional(t.Union([AssistantsApiResponseFormatOptionSchema, t.Null()])),
  },
  {
    title: 'Assistant',
    description: 'Represents an `assistant` that can call the model and use tools.',
    deprecated: true,
  },
)

export const ThreadObjectSchema = t.Object(
  {
    id: t.String({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: t.Literal('thread', { description: 'The object type, which is always `thread`.' }),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) for when the thread was created.',
    }),
    tool_resources: t.Union([
      t.Object(
        {
          code_interpreter: t.Optional(
            t.Object({
              file_ids: t.Optional(
                t.Array(t.String(), {
                  maxItems: 20,
                  description:
                    'A list of [file](https://developers.openai.com/api/reference/resources/files) IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n',
                  default: [],
                }),
              ),
            }),
          ),
          file_search: t.Optional(
            t.Object({
              vector_store_ids: t.Optional(
                t.Array(t.String(), {
                  maxItems: 1,
                  description:
                    'The [vector store](https://developers.openai.com/api/reference/resources/vector_stores) attached to this thread. There can be a maximum of 1 vector store attached to the thread.\n',
                }),
              ),
            }),
          ),
        },
        {
          description:
            "A set of resources that are made available to the assistant's tools in this thread. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n",
        },
      ),
      t.Null(),
    ]),
    metadata: MetadataSchema,
  },
  {
    title: 'Thread',
    description:
      'Represents a thread that contains [messages](https://developers.openai.com/api/docs/assistants/migration).',
  },
)

export const ThreadStreamEventSchema = t.Object(
  {
    enabled: t.Optional(t.Boolean({ description: 'Whether to enable input audio transcription.' })),
    event: t.Literal('thread.created'),
    data: ThreadObjectSchema,
  },
  {
    description:
      'Occurs when a new [thread](https://developers.openai.com/api/docs/assistants/migration) is created.',
  },
)

export const RunToolCallObjectSchema = t.Object(
  {
    id: t.String({
      description:
        'The ID of the tool call. This ID must be referenced when you submit the tool outputs in using the [Submit tool outputs to run](https://developers.openai.com/api/docs/assistants/migration) endpoint.',
    }),
    type: t.Literal('function', {
      description:
        'The type of tool call the output is required for. For now, this is always `function`.',
    }),
    function: t.Object(
      {
        name: t.String({ description: 'The name of the function.' }),
        arguments: t.String({
          description: 'The arguments that the model expects you to pass to the function.',
        }),
      },
      { description: 'The function definition.' },
    ),
  },
  { description: 'Tool call objects' },
)

export const RunCompletionUsageSchema = t.Union([
  t.Object(
    {
      completion_tokens: t.Integer({
        maximum: 9007199254740991,
        description: 'Number of completion tokens used over the course of the run.',
      }),
      prompt_tokens: t.Integer({
        maximum: 9007199254740991,
        description: 'Number of prompt tokens used over the course of the run.',
      }),
      total_tokens: t.Integer({
        maximum: 9007199254740991,
        description: 'Total number of tokens used (prompt + completion).',
      }),
    },
    {
      description:
        'Usage statistics related to the run. This value will be `null` if the run is not in a terminal state (i.e. `in_progress`, `queued`, etc.).',
    },
  ),
  t.Null(),
])

export const TruncationObjectSchema = t.Object(
  {
    type: t.UnionEnum(['auto', 'last_messages'], {
      description:
        'The truncation strategy to use for the thread. The default is `auto`. If set to `last_messages`, the thread will be truncated to the n most recent messages in the thread. When set to `auto`, messages in the middle of the thread will be dropped to fit the context length of the model, `max_prompt_tokens`.',
      default: undefined,
    }),
    last_messages: t.Optional(
      t.Union([
        t.Integer({
          minimum: 1,
          maximum: 9007199254740991,
          description:
            'The number of most recent messages from the thread when constructing the context for the run.',
        }),
        t.Null(),
      ]),
    ),
  },
  {
    title: 'Thread Truncation Controls',
    description:
      'Controls for how a thread will be truncated prior to the run. Use this to control the initial context window of the run.',
  },
)

export const AssistantsNamedToolChoiceSchema = t.Object(
  {
    type: t.UnionEnum(['function', 'code_interpreter', 'file_search'], {
      description: 'The type of the tool. If type is `function`, the function name must be set',
      default: undefined,
    }),
    function: t.Optional(
      t.Object({ name: t.String({ description: 'The name of the function to call.' }) }),
    ),
  },
  {
    description:
      'Specifies a tool the model should use. Use to force the model to call a specific tool.',
  },
)

export const AssistantsApiToolChoiceOptionSchema = t.Union(
  [
    t.UnionEnum(['none', 'auto', 'required'], {
      description:
        '`none` means the model will not call any tools and instead generates a message. `auto` means the model can pick between generating a message or calling one or more tools. `required` means the model must call one or more tools before responding to the user.\n',
      default: undefined,
    }),
    AssistantsNamedToolChoiceSchema,
  ],
  {
    description:
      'Controls which (if any) tool is called by the model.\n`none` means the model will not call any tools and instead generates a message.\n`auto` is the default value and means the model can pick between generating a message or calling one or more tools.\n`required` means the model must call one or more tools before responding to the user.\nSpecifying a particular tool like `{"type": "file_search"}` or `{"type": "function", "function": {"name": "my_function"}}` forces the model to call that tool.\n',
  },
)

export const ParallelToolCallsSchema = t.Boolean({
  description:
    'Whether to enable [parallel function calling](https://developers.openai.com/api/docs/guides/function-calling#parallel-function-calling) during tool use.',
  default: true,
})

export const RunObjectSchema = t.Object(
  {
    id: t.String({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: t.Literal('thread.run', {
      description: 'The object type, which is always `thread.run`.',
    }),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) for when the run was created.',
    }),
    thread_id: t.String({
      description:
        'The ID of the [thread](https://developers.openai.com/api/docs/assistants/migration) that was executed on as a part of this run.',
    }),
    assistant_id: t.String({
      description:
        'The ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for execution of this run.',
    }),
    status: t.UnionEnum(
      [
        'queued',
        'in_progress',
        'requires_action',
        'cancelling',
        'cancelled',
        'failed',
        'completed',
        'incomplete',
        'expired',
      ],
      {
        description:
          'The status of the run, which can be either `queued`, `in_progress`, `requires_action`, `cancelling`, `cancelled`, `failed`, `completed`, `incomplete`, or `expired`.',
        default: undefined,
      },
    ),
    required_action: t.Union([
      t.Object(
        {
          type: t.Literal('submit_tool_outputs', {
            description: 'For now, this is always `submit_tool_outputs`.',
          }),
          submit_tool_outputs: t.Object(
            {
              tool_calls: t.Array(RunToolCallObjectSchema, {
                description: 'A list of the relevant tool calls.',
              }),
            },
            { description: 'Details on the tool outputs needed for this run to continue.' },
          ),
        },
        {
          description:
            'Details on the action required to continue the run. Will be `null` if no action is required.',
        },
      ),
      t.Null(),
    ]),
    last_error: t.Union([
      t.Object(
        {
          code: t.UnionEnum(['server_error', 'rate_limit_exceeded', 'invalid_prompt'], {
            description: 'One of `server_error`, `rate_limit_exceeded`, or `invalid_prompt`.',
            default: undefined,
          }),
          message: t.String({ description: 'A human-readable description of the error.' }),
        },
        {
          description:
            'The last error associated with this run. Will be `null` if there are no errors.',
        },
      ),
      t.Null(),
    ]),
    expires_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run will expire.',
      }),
      t.Null(),
    ]),
    started_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run was started.',
      }),
      t.Null(),
    ]),
    cancelled_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run was cancelled.',
      }),
      t.Null(),
    ]),
    failed_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run failed.',
      }),
      t.Null(),
    ]),
    completed_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run was completed.',
      }),
      t.Null(),
    ]),
    incomplete_details: t.Union([
      t.Object(
        {
          reason: t.Optional(
            t.UnionEnum(['max_completion_tokens', 'max_prompt_tokens'], {
              description:
                'The reason why the run is incomplete. This will point to which specific token limit was reached over the course of the run.',
              default: undefined,
            }),
          ),
        },
        {
          description:
            'Details on why the run is incomplete. Will be `null` if the run is not incomplete.',
        },
      ),
      t.Null(),
    ]),
    model: t.String({
      description:
        'The model that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
    }),
    instructions: t.String({
      description:
        'The instructions that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
    }),
    tools: t.Array(
      t.Union([
        AssistantToolsCodeSchema,
        AssistantToolsFileSearchSchema,
        AssistantToolsFunctionSchema,
      ]),
      {
        maxItems: 20,
        description:
          'The list of tools that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
        default: [],
      },
    ),
    metadata: MetadataSchema,
    usage: RunCompletionUsageSchema,
    temperature: t.Optional(
      t.Union([
        t.Number({
          description: 'The sampling temperature used for this run. If not set, defaults to 1.',
        }),
        t.Null(),
      ]),
    ),
    top_p: t.Optional(
      t.Union([
        t.Number({
          description: 'The nucleus sampling value used for this run. If not set, defaults to 1.',
        }),
        t.Null(),
      ]),
    ),
    max_prompt_tokens: t.Union([
      t.Integer({
        minimum: 256,
        maximum: 9007199254740991,
        description:
          'The maximum number of prompt tokens specified to have been used over the course of the run.\n',
      }),
      t.Null(),
    ]),
    max_completion_tokens: t.Union([
      t.Integer({
        minimum: 256,
        maximum: 9007199254740991,
        description:
          'The maximum number of completion tokens specified to have been used over the course of the run.\n',
      }),
      t.Null(),
    ]),
    truncation_strategy: t.Union([TruncationObjectSchema, t.Null()]),
    tool_choice: t.Union([AssistantsApiToolChoiceOptionSchema, t.Null()]),
    parallel_tool_calls: ParallelToolCallsSchema,
    response_format: t.Union([AssistantsApiResponseFormatOptionSchema, t.Null()]),
  },
  {
    title: 'A run on a thread',
    description:
      'Represents an execution run on a [thread](https://developers.openai.com/api/docs/assistants/migration).',
  },
)

