export const RunStepObjectSchema = t.Object(
  {
    id: t.String({
      description: 'The identifier of the run step, which can be referenced in API endpoints.',
    }),
    object: t.Literal('thread.run.step', {
      description: 'The object type, which is always `thread.run.step`.',
    }),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) for when the run step was created.',
    }),
    assistant_id: t.String({
      description:
        'The ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) associated with the run step.',
    }),
    thread_id: t.String({
      description:
        'The ID of the [thread](https://developers.openai.com/api/docs/assistants/migration) that was run.',
    }),
    run_id: t.String({
      description:
        'The ID of the [run](https://developers.openai.com/api/docs/assistants/migration) that this run step is a part of.',
    }),
    type: t.UnionEnum(['message_creation', 'tool_calls'], {
      description: 'The type of run step, which can be either `message_creation` or `tool_calls`.',
      default: undefined,
    }),
    status: t.UnionEnum(['in_progress', 'cancelled', 'failed', 'completed', 'expired'], {
      description:
        'The status of the run step, which can be either `in_progress`, `cancelled`, `failed`, `completed`, or `expired`.',
      default: undefined,
    }),
    step_details: t.Union(
      [RunStepDetailsMessageCreationObjectSchema, RunStepDetailsToolCallsObjectSchema],
      { description: 'The details of the run step.' },
    ),
    last_error: t.Union([
      t.Object(
        {
          code: t.UnionEnum(['server_error', 'rate_limit_exceeded'], {
            description: 'One of `server_error` or `rate_limit_exceeded`.',
            default: undefined,
          }),
          message: t.String({ description: 'A human-readable description of the error.' }),
        },
        {
          description:
            'The last error associated with this run step. Will be `null` if there are no errors.',
        },
      ),
      t.Null(),
    ]),
    expired_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description:
          'The Unix timestamp (in seconds) for when the run step expired. A step is considered expired if the parent run is expired.',
      }),
      t.Null(),
    ]),
    cancelled_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run step was cancelled.',
      }),
      t.Null(),
    ]),
    failed_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run step failed.',
      }),
      t.Null(),
    ]),
    completed_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the run step completed.',
      }),
      t.Null(),
    ]),
    metadata: MetadataSchema,
    usage: RunStepCompletionUsageSchema,
  },
  { title: 'Run steps', description: 'Represents a step in execution of a run.\n' },
)

