export const MessageObjectSchema = t.Object(
  {
    id: t.String({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: t.Literal('thread.message', {
      description: 'The object type, which is always `thread.message`.',
    }),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) for when the message was created.',
    }),
    thread_id: t.String({
      description:
        'The [thread](https://developers.openai.com/api/docs/assistants/migration) ID that this message belongs to.',
    }),
    status: t.UnionEnum(['in_progress', 'incomplete', 'completed'], {
      description:
        'The status of the message, which can be either `in_progress`, `incomplete`, or `completed`.',
      default: undefined,
    }),
    incomplete_details: t.Union([
      t.Object(
        {
          reason: t.UnionEnum(
            ['content_filter', 'max_tokens', 'run_cancelled', 'run_expired', 'run_failed'],
            { description: 'The reason the message is incomplete.', default: undefined },
          ),
        },
        { description: 'On an incomplete message, details about why the message is incomplete.' },
      ),
      t.Null(),
    ]),
    completed_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) for when the message was completed.',
      }),
      t.Null(),
    ]),
    incomplete_at: t.Union([
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description:
          'The Unix timestamp (in seconds) for when the message was marked as incomplete.',
      }),
      t.Null(),
    ]),
    role: t.UnionEnum(['user', 'assistant'], {
      description: 'The entity that produced the message. One of `user` or `assistant`.',
      default: undefined,
    }),
    content: t.Array(
      t.Union([
        MessageContentImageFileObjectSchema,
        MessageContentImageUrlObjectSchema,
        MessageContentTextObjectSchema,
        MessageContentRefusalObjectSchema,
      ]),
      { description: 'The content of the message in array of text and/or images.' },
    ),
    assistant_id: t.Union([
      t.String({
        description:
          'If applicable, the ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) that authored this message.',
      }),
      t.Null(),
    ]),
    run_id: t.Union([
      t.String({
        description:
          'The ID of the [run](https://developers.openai.com/api/docs/assistants/migration) associated with the creation of this message. Value is `null` when messages are created manually using the create message or create thread endpoints.',
      }),
      t.Null(),
    ]),
    attachments: t.Union([
      t.Array(
        t.Object({
          file_id: t.Optional(
            t.String({ description: 'The ID of the file to attach to the message.' }),
          ),
          tools: t.Optional(
            t.Array(t.Union([AssistantToolsCodeSchema, AssistantToolsFileSearchTypeOnlySchema]), {
              description: 'The tools to add this file to.',
            }),
          ),
        }),
        {
          description: 'A list of files attached to the message, and the tools they were added to.',
        },
      ),
      t.Null(),
    ]),
    metadata: MetadataSchema,
  },
  {
    title: 'The message object',
    description:
      'Represents a message within a [thread](https://developers.openai.com/api/docs/assistants/migration).',
  },
)

