export const CreateChatCompletionResponseSchema = t.Object(
  {
    id: t.String({ description: 'A unique identifier for the chat completion.' }),
    choices: t.Array(
      t.Object({
        finish_reason: t.UnionEnum(
          ['stop', 'length', 'tool_calls', 'content_filter', 'function_call'],
          {
            description:
              'The reason the model stopped generating tokens. This will be `stop` if the model hit a natural stop point or a provided stop sequence,\n`length` if the maximum number of tokens specified in the request was reached,\n`content_filter` if content was omitted due to a flag from our content filters,\n`tool_calls` if the model called a tool, or `function_call` (deprecated) if the model called a function.\nRead the [Model Spec](https://model-spec.openai.com/2025-12-18.html) for more.\n',
            default: undefined,
          },
        ),
        index: t.Integer({
          maximum: 9007199254740991,
          description: 'The index of the choice in the list of choices.',
        }),
        message: ChatCompletionResponseMessageSchema,
        logprobs: t.Union([
          t.Object(
            {
              content: t.Union([
                t.Array(ChatCompletionTokenLogprobSchema, {
                  description: 'A list of message content tokens with log probability information.',
                }),
                t.Null(),
              ]),
              refusal: t.Union([
                t.Array(ChatCompletionTokenLogprobSchema, {
                  description: 'A list of message refusal tokens with log probability information.',
                }),
                t.Null(),
              ]),
            },
            { description: 'Log probability information for the choice.' },
          ),
          t.Null(),
        ]),
      }),
      {
        description:
          'A list of chat completion choices. Can be more than one if `n` is greater than 1.',
      },
    ),
    created: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) of when the chat completion was created.',
    }),
    model: t.String({ description: 'The model used for the chat completion.' }),
    metadata: t.Optional(MetadataSchema),
    service_tier: t.Optional(ServiceTierSchema),
    system_fingerprint: t.Optional(
      t.String({
        description:
          'This fingerprint represents the backend configuration that the model runs with.\n\nCan be used in conjunction with the `seed` request parameter to understand when backend changes have been made that might impact determinism.\n',
        deprecated: true,
      }),
    ),
    object: t.Literal('chat.completion', {
      description: 'The object type, which is always `chat.completion`.',
    }),
    usage: t.Optional(CompletionUsageSchema),
    moderation: t.Optional(t.Union([ChatCompletionModerationSchema, t.Null()])),
  },
  {
    description:
      'Represents a chat completion response returned by model, based on the provided input.',
  },
)

