export const ChatCompletionStreamOptionsSchema = t.Union([
  t.Object(
    {
      include_usage: t.Optional(
        t.Boolean({
          description:
            'If set, an additional chunk will be streamed before the `data: [DONE]`\nmessage. The `usage` field on this chunk shows the token usage statistics\nfor the entire request, and the `choices` field will always be an empty\narray.\n\nAll other chunks will also include a `usage` field, but with a null\nvalue. **NOTE:** If the stream is interrupted, you may not receive the\nfinal usage chunk which contains the total token usage for the request.\n',
        }),
      ),
      include_obfuscation: t.Optional(
        t.Boolean({
          description:
            'When true, stream obfuscation will be enabled. Stream obfuscation adds\nrandom characters to an `obfuscation` field on streaming delta events to\nnormalize payload sizes as a mitigation to certain side-channel attacks.\nThese obfuscation fields are included by default, but add a small amount\nof overhead to the data stream. You can set `include_obfuscation` to\nfalse to optimize for bandwidth if you trust the network links between\nyour application and the OpenAI API.\n',
        }),
      ),
    },
    { description: 'Options for streaming response. Only set this when you set `stream: true`.\n' },
  ),
  t.Null(),
])

export const ChatCompletionStreamResponseDeltaSchema = t.Object(
  {
    audio: t.Optional(
      t.Object(
        {
          id: t.Optional(t.String({ description: 'Unique identifier for this audio response.' })),
          expires_at: t.Optional(
            t.Integer({
              format: 'unixtime',
              maximum: 9007199254740991,
              description:
                'The Unix timestamp (in seconds) for when this audio response will no\nlonger be accessible on the server for use in multi-turn conversations.\n',
            }),
          ),
          data: t.Optional(
            t.String({
              description:
                'Base64 encoded audio bytes generated by the model, in the format\nspecified in the request.\n',
            }),
          ),
          transcript: t.Optional(
            t.String({ description: 'Transcript text from this audio chunk.' }),
          ),
        },
        {
          description:
            'A partial audio response. Audio chunks may carry an ID, base64 data, or\ntranscript text; the final audio update contains only its expiry timestamp.\n',
        },
      ),
    ),
    content: t.Optional(
      t.Union([t.String({ description: 'The contents of the chunk message.' }), t.Null()]),
    ),
    function_call: t.Optional(
      t.Object(
        {
          arguments: t.Optional(
            t.String({
              description:
                'The arguments to call the function with, as generated by the model in JSON format. Note that the model does not always generate valid JSON, and may hallucinate parameters not defined by your function schema. Validate the arguments in your code before calling your function.',
            }),
          ),
          name: t.Optional(t.String({ description: 'The name of the function to call.' })),
        },
        {
          description:
            'Deprecated and replaced by `tool_calls`. The name and arguments of a function that should be called, as generated by the model.',
          deprecated: true,
        },
      ),
    ),
    tool_calls: t.Optional(t.Array(ChatCompletionMessageToolCallChunkSchema)),
    role: t.Optional(
      t.UnionEnum(['developer', 'system', 'user', 'assistant', 'tool'], {
        description: 'The role of the author of this message.',
        default: undefined,
      }),
    ),
    refusal: t.Optional(
      t.Union([t.String({ description: 'The refusal message generated by the model.' }), t.Null()]),
    ),
  },
  {
    description:
      'A chat completion delta generated by streamed model responses.\nStreamed audio can arrive in partial updates with an ID, base64 data, or\ntranscript text. The final audio update contains only its expiry timestamp.\n',
  },
)

