export const EvalRunSchema = t.Object(
  {
    object: t.Literal('eval.run', {
      description: 'The type of the object. Always "eval.run".',
      default: 'eval.run',
    }),
    id: t.String({ description: 'Unique identifier for the evaluation run.' }),
    eval_id: t.String({ description: 'The identifier of the associated evaluation.' }),
    status: t.String({ description: 'The status of the evaluation run.' }),
    model: t.Union([
      t.String({ description: 'The model that is evaluated, if applicable.' }),
      t.Null(),
    ]),
    name: t.Union([t.String({ description: 'The name of the evaluation run.' }), t.Null()]),
    created_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'Unix timestamp (in seconds) when the evaluation run was created.',
    }),
    report_url: t.String({
      format: 'uri',
      description: 'The URL to the rendered evaluation run report on the UI dashboard.',
    }),
    result_counts: t.Object(
      {
        total: t.Integer({
          maximum: 9007199254740991,
          description: 'Total number of executed output items.',
        }),
        errored: t.Integer({
          maximum: 9007199254740991,
          description: 'Number of output items that resulted in an error.',
        }),
        failed: t.Integer({
          maximum: 9007199254740991,
          description: 'Number of output items that failed to pass the evaluation.',
        }),
        passed: t.Integer({
          maximum: 9007199254740991,
          description: 'Number of output items that passed the evaluation.',
        }),
      },
      { description: 'Counters summarizing the outcomes of the evaluation run.' },
    ),
    per_model_usage: t.Union([
      t.Array(
        t.Object({
          model_name: t.String({ description: 'The name of the model.' }),
          invocation_count: t.Integer({
            maximum: 9007199254740991,
            description: 'The number of invocations.',
          }),
          prompt_tokens: t.Integer({
            maximum: 9007199254740991,
            description: 'The number of prompt tokens used.',
          }),
          completion_tokens: t.Integer({
            maximum: 9007199254740991,
            description: 'The number of completion tokens generated.',
          }),
          total_tokens: t.Integer({
            maximum: 9007199254740991,
            description: 'The total number of tokens used.',
          }),
          cached_tokens: t.Integer({
            maximum: 9007199254740991,
            description: 'The number of tokens retrieved from cache.',
          }),
        }),
        { description: 'Usage statistics for each model during the evaluation run.' },
      ),
      t.Null(),
    ]),
    per_testing_criteria_results: t.Union([
      t.Array(
        t.Object({
          testing_criteria: t.String({ description: 'A description of the testing criteria.' }),
          passed: t.Integer({
            maximum: 9007199254740991,
            description: 'Number of tests passed for this criteria.',
          }),
          failed: t.Integer({
            maximum: 9007199254740991,
            description: 'Number of tests failed for this criteria.',
          }),
        }),
        { description: 'Results per testing criteria applied during the evaluation run.' },
      ),
      t.Null(),
    ]),
    data_source: t.Union(
      [
        CreateEvalJsonlRunDataSourceSchema,
        CreateEvalCompletionsRunDataSourceSchema,
        CreateEvalResponsesRunDataSourceSchema,
      ],
      { description: "Information about the run's data source." },
    ),
    metadata: MetadataSchema,
    error: t.Union([EvalApiErrorSchema, t.Null()]),
  },
  { title: 'EvalRun', description: 'A schema representing an evaluation run.\n' },
)

