export const LiveMCPToolInputParamSchema = t.Object({
  type: t.Literal('mcp', { default: 'mcp' }),
  server_label: t.Optional(
    t.String({
      pattern: '^[A-Za-z][A-Za-z0-9_-]*$',
      maxLength: 128,
      description: 'A label used to identify the MCP server.',
    }),
  ),
  server_url: t.Optional(
    t.Union([
      t.String({ format: 'uri', description: 'The URL of the MCP server to connect to.' }),
      t.Null(),
    ]),
  ),
  server_description: t.Optional(
    t.Union([
      t.String({ description: 'An optional human-readable description of the MCP server.' }),
      t.Null(),
    ]),
  ),
  authorization: t.Optional(
    t.Union(
      [
        t.String({
          description:
            'The authorization token to use when connecting to the MCP server or connector.',
        }),
        t.Null(),
      ],
      { description: 'This value is omitted from returned Live session data.', writeOnly: true },
    ),
  ),
  headers: t.Optional(
    t.Union(
      [
        t.Record(t.String(), t.String(), {
          description: 'Optional HTTP headers to send when connecting to the MCP server.',
        }),
        t.Null(),
      ],
      { description: 'This value is omitted from returned Live session data.', writeOnly: true },
    ),
  ),
  allowed_tools: t.Optional(
    t.Union([
      t.Union([t.Array(t.String()), LiveMCPToolFilterParamSchema], {
        description: 'A list of MCP tool names that are allowed for this server.',
      }),
      t.Null(),
    ]),
  ),
  require_approval: t.Optional(
    t.Union([
      t.Union([LiveMCPRequireApprovalFilterParamSchema, LiveMCPRequireApprovalApiEnumSchema], {
        description: 'Controls which MCP tools require explicit user approval before execution.',
      }),
      t.Null(),
    ]),
  ),
  connector_id: t.Optional(
    t.Union([
      t.String({
        description:
          'The ID of a built-in MCP connector. This field is deprecated for models released after September 1, 2026. Use `server_url` to connect to a remote MCP server, or `tunnel_id` to connect to a local MCP server.',
        deprecated: true,
      }),
      t.Null(),
    ]),
  ),
  tunnel_id: t.Optional(
    t.Union([
      t.String({
        pattern: '^tunnel_[a-z0-9]{32}$',
        description: 'The Secure MCP Tunnel ID to use instead of a direct server URL.',
      }),
      t.Null(),
    ]),
  ),
  allowed_callers: t.Optional(
    t.Union([
      t.Array(LiveCallableToolAllowedCallerSchema, {
        minItems: 1,
        description: 'The tool invocation context(s).',
      }),
      t.Null(),
    ]),
  ),
  defer_loading: t.Optional(
    t.Union([
      t.Boolean({
        description: 'Whether this MCP tool should be deferred and discovered via tool search.',
      }),
      t.Null(),
    ]),
  ),
})

