export const LiveSessionResourceParamSchema = t.Object(
  {
    model: ModelIdsLiveSchema,
    safety_identifier: t.Optional(
      t.Union([
        t.String({
          maxLength: 128,
          description:
            'A stable identifier for your end user, used for safety monitoring and abuse detection.',
        }),
        t.Null(),
      ]),
    ),
    instructions: t.Optional(
      t.Union([
        t.String({
          description:
            'Frontend instructions for voice, conversation, interruptions, and when to delegate. Start with the [Live prompting guide](https://developers.openai.com/api/docs/guides/live-prompting); put business rules and tool workflows in a separate [backend prompt](https://developers.openai.com/api/docs/guides/live-delegation#start-with-your-existing-backend-prompt). Limited to 16,384 client-supplied tokens. Omitted or blank instructions use server defaults. Immutable after startup.',
        }),
        t.Null(),
      ]),
    ),
    input: t.Optional(
      t.Array(LiveInitialItemSchema, {
        maxItems: 128,
        description:
          'Ordered text-only history supplied before startup. Supports developer, user, and assistant messages with one text part each; at most 128 messages and a configured rendered-token limit (8,192 by default).',
      }),
    ),
    audio: t.Optional(LiveInitialSessionAudioParamSchema),
    delegation: t.Optional(
      t.Union([
        t.Union(
          [
            LiveClientDelegationParamSchema,
            LiveResponsesDelegationParamSchema,
            LiveDecisionsDelegationParamSchema,
          ],
          {
            description:
              'Who handles tasks delegated by the Live model. Omitted or null selects your application; use `responses` or `decisions` to delegate to the corresponding API.',
          },
        ),
        t.Null(),
      ]),
    ),
    triggers: t.Optional(
      t.Array(LiveDecisionTriggerInputParamSchema, {
        maxItems: 2,
        description:
          'At most one Decisions trigger per transcript event type. Triggers run independently of delegation. On update, omit triggers to keep the current configuration, send a list to replace it, or send an empty list to disable triggers.',
      }),
    ),
    store: t.Optional(
      t.Boolean({
        description:
          'Whether to store the session for later forking and recording download. Defaults to false for new sessions.',
      }),
    ),
    client: t.Optional(LiveClientConfigParamSchema),
    id: t.String({
      description:
        'The unique ID of the Live session. Use this ID for sideband connections, forking, and recording download.',
    }),
    expires_at: t.Integer({
      maximum: 9007199254740991,
      description: 'The Unix timestamp, in seconds, at which the Live session expires.',
    }),
    status: t.Literal('active', {
      description:
        'The status of the session snapshot. Always `active`, including the final snapshot in session.closed; use the event type to determine that the session has closed.',
      default: 'active',
    }),
  },
  { description: 'The resolved Live session configuration and server-assigned session metadata.' },
)

