export const LiveSessionClosedSchema = t.Object(
  {
    event_id: t.String({ description: 'The unique ID of the Live server event.' }),
    client_event_id: t.Optional(
      t.String({
        description:
          'The event_id of the client command associated with this server event, when supplied.',
      }),
    ),
    type: t.Literal('session.closed', {
      description: 'The event type, always `session.closed`.',
      default: 'session.closed',
    }),
    reason: t.Union(
      [
        t.Literal('close_requested', { default: 'close_requested' }),
        t.Literal('expired', { default: 'expired' }),
        t.Literal('content', { default: 'content' }),
        t.Literal('remote_hangup', { default: 'remote_hangup' }),
        t.Literal('connection_lost', { default: 'connection_lost' }),
      ],
      {
        description:
          'Why the Live session ended: `close_requested` for an application close or hangup request, `expired` for the session duration limit, `content` for a safety filter, `remote_hangup` for a graceful remote disconnect, or `connection_lost` for an unexpected primary or upstream disconnection.',
      },
    ),
    session: LiveSessionResourceParamSchema,
    usage: LiveSessionUsageSchema,
  },
  {
    example: {
      type: 'session.closed',
      event_id: 'evt_closed_001',
      client_event_id: 'evt_close_001',
      reason: 'close_requested',
      session: {
        id: 'live_abc123',
        model: 'gpt-live-1.1',
        status: 'active',
        expires_at: 1788555600,
        instructions:
          'Help the caller plan a restaurant reservation. Confirm details before booking.',
        input: [],
        audio: { format: { type: 'audio/pcm', rate: 24000 }, output: { voice: 'marin' } },
        delegation: { type: 'client' },
      },
      usage: { seconds: 45 },
    },
    description:
      'Returned after the Live session finishes finalizing, with the close reason, final session snapshot, and cumulative audio usage. A connection closing without this event does not confirm successful finalization.',
  },
)

