export const ResponseSteerPendingEventSchema = t.Object(
  {
    type: t.Literal('response.steer.pending', {
      description: 'The event discriminator. Always `response.steer.pending`.',
    }),
    sequence_number: t.Integer({
      maximum: 9007199254740991,
      description: 'The sequence number for this event.',
    }),
    steer: t.Object(
      {
        id: t.String({ description: 'The ID assigned to the steering submission.' }),
        previous_response_id: t.String({ description: 'The ID of the response being steered.' }),
      },
      { description: 'The steering submission that remains queued.' },
    ),
    reason: ResponseSteerPendingReasonSchema,
    required_input: t.Array(ResponseSteerRequiredInputSchema, {
      minItems: 1,
      description:
        'Input stubs identifying outstanding client-owned tool results or\napproval decisions. Each stub contains identifying fields only; the\nclient supplies the result before including it in `response.create`.\n',
    }),
    stream_id: t.Optional(
      t.String({
        description:
          "The WebSocket lane that emitted this event. This field is present when\nthe target response's `response.create` event supplied a `stream_id`.\n",
      }),
    ),
  },
  {
    title: 'ResponseSteerPendingEvent',
    description:
      "Emitted when accepted steering input remains queued after the target\nresponse completes. The server still owns the input. Do not resend it.\nThe successor's `response.created` event is the commit point.\n\nWhen `reason` is `waiting_for_required_input`, this event follows\n`response.completed` while the response waits for the tool results or\napproval decisions identified by `required_input`. Copy those stubs, fill\ntheir result fields using the ordinary `response.create` input schemas,\nand submit one continuation per parent with the same `previous_response_id`\nand WebSocket lane. Use saved results without rerunning tools. The queued\nsteering input is prepended in submission order to the continuation's\ninput. That explicit request retains its own settings.\n\nThis notification is emitted at most once per steering submission. Multiple\nsubmissions for the same parent can report the same required inputs; they\ndo not each require a separate continuation.\n",
  },
)

