export const RunGraderResponseSchema = t.Object({
  reward: t.Number(),
  metadata: t.Object({
    name: t.String(),
    type: t.String(),
    errors: t.Object({
      formula_parse_error: t.Boolean(),
      sample_parse_error: t.Boolean(),
      truncated_observation_error: t.Boolean(),
      unresponsive_reward_error: t.Boolean(),
      invalid_variable_error: t.Boolean(),
      other_error: t.Boolean(),
      python_grader_server_error: t.Boolean(),
      python_grader_server_error_type: t.Union([t.String(), t.Null()]),
      python_grader_runtime_error: t.Boolean(),
      python_grader_runtime_error_details: t.Union([t.String(), t.Null()]),
      model_grader_server_error: t.Boolean(),
      model_grader_refusal_error: t.Boolean(),
      model_grader_parse_error: t.Boolean(),
      model_grader_server_error_details: t.Union([t.String(), t.Null()]),
    }),
    execution_time: t.Number(),
    scores: t.Record(t.String(), t.Unknown()),
    token_usage: t.Union([
      t.Object({
        prompt_tokens: t.Integer({ maximum: 9007199254740991 }),
        total_tokens: t.Integer({ maximum: 9007199254740991 }),
        completion_tokens: t.Optional(
          t.Union([t.Integer({ maximum: 9007199254740991 }), t.Null()]),
        ),
        cached_tokens: t.Optional(t.Union([t.Integer({ maximum: 9007199254740991 }), t.Null()])),
      }),
      t.Null(),
    ]),
    sampled_model_name: t.Union([t.String(), t.Null()]),
  }),
  sub_rewards: t.Record(t.String(), t.Unknown()),
  model_grader_token_usage_per_model: t.Record(t.String(), t.Unknown()),
})

