export const UserSchema = t.Object(
  {
    object: t.Literal('organization.user', {
      description: 'The object type, which is always `organization.user`',
    }),
    id: t.String({ description: 'The identifier, which can be referenced in API endpoints' }),
    name: t.Optional(t.Union([t.String(), t.Null()], { description: 'The name of the user' })),
    email: t.Optional(
      t.Union([t.String(), t.Null()], { description: 'The email address of the user' }),
    ),
    role: t.Optional(t.Union([t.String(), t.Null()], { description: '`owner` or `reader`' })),
    added_at: t.Integer({
      format: 'unixtime',
      maximum: 9007199254740991,
      description: 'The Unix timestamp (in seconds) of when the user was added.',
    }),
    is_default: t.Optional(
      t.Boolean({ description: "Whether this is the organization's default user." }),
    ),
    created: t.Optional(
      t.Integer({
        format: 'unixtime',
        maximum: 9007199254740991,
        description: 'The Unix timestamp (in seconds) of when the user was created.',
      }),
    ),
    user: t.Optional(
      t.Object(
        {
          object: t.Literal('user'),
          id: t.String(),
          email: t.Optional(t.Union([t.String(), t.Null()])),
          name: t.Optional(t.Union([t.String(), t.Null()])),
          picture: t.Optional(t.Union([t.String(), t.Null()])),
          enabled: t.Optional(t.Union([t.Boolean(), t.Null()])),
          banned: t.Optional(t.Union([t.Boolean(), t.Null()])),
          banned_at: t.Optional(
            t.Union([t.Integer({ format: 'unixtime', maximum: 9007199254740991 }), t.Null()]),
          ),
        },
        { description: 'Nested user details.' },
      ),
    ),
    is_service_account: t.Optional(
      t.Boolean({ description: 'Whether the user is a service account.' }),
    ),
    is_scale_tier_authorized_purchaser: t.Optional(
      t.Union([t.Boolean(), t.Null()], {
        description: 'Whether the user is an authorized purchaser for Scale Tier.',
      }),
    ),
    is_scim_managed: t.Optional(
      t.Boolean({ description: 'Whether the user is managed through SCIM.' }),
    ),
    api_key_last_used_at: t.Optional(
      t.Union([t.Integer({ format: 'unixtime', maximum: 9007199254740991 }), t.Null()], {
        description: "The Unix timestamp (in seconds) of the user's last API key usage.",
      }),
    ),
    technical_level: t.Optional(
      t.Union([t.String(), t.Null()], {
        description: 'The technical level metadata for the user.',
      }),
    ),
    developer_persona: t.Optional(
      t.Union([t.String(), t.Null()], {
        description: 'The developer persona metadata for the user.',
      }),
    ),
    projects: t.Optional(
      t.Union(
        [
          t.Object({
            object: t.Literal('list'),
            data: t.Array(
              t.Object({
                id: t.Optional(t.Union([t.String(), t.Null()])),
                name: t.Optional(t.Union([t.String(), t.Null()])),
                role: t.Optional(t.Union([t.String(), t.Null()])),
              }),
            ),
          }),
          t.Null(),
        ],
        { description: 'Projects associated with the user, if included.' },
      ),
    ),
  },
  { description: 'Represents an individual `user` within an organization.' },
)

