export const BetaCallableToolAllowedCallerSchema = t.UnionEnum(['direct', 'programmatic'], {
  default: undefined,
})

export const BetaFunctionToolSchema = t.Object(
  {
    type: t.Literal('function', {
      description: 'The type of the function tool. Always `function`.',
      default: 'function',
    }),
    name: t.String({ description: 'The name of the function to call.' }),
    async: t.Optional(t.Boolean()),
    description: t.Optional(
      t.Union([
        t.String({
          description:
            'A description of the function. Used by the model to determine whether or not to call the function.',
        }),
        t.Null(),
      ]),
    ),
    parameters: t.Union([
      t.Record(t.String(), t.Unknown(), {
        description: 'A JSON schema object describing the parameters of the function.',
      }),
      t.Null(),
    ]),
    output_schema: t.Optional(
      t.Union([
        t.Record(t.String(), t.Unknown(), {
          description:
            'A JSON schema object describing the JSON value encoded in string outputs for this function.',
        }),
        t.Null(),
      ]),
    ),
    strict: t.Union([
      t.Boolean({
        description: 'Whether strict parameter validation is enforced for this function tool.',
      }),
      t.Null(),
    ]),
    defer_loading: t.Optional(
      t.Boolean({ description: 'Whether this function is deferred and loaded via tool search.' }),
    ),
    allowed_callers: t.Optional(
      t.Union([
        t.Array(BetaCallableToolAllowedCallerSchema, {
          description: 'The tool invocation context(s).',
        }),
        t.Null(),
      ]),
    ),
  },
  {
    title: 'Function',
    description:
      'Defines a function in your own code the model can choose to call. Learn more about [function calling](https://developers.openai.com/api/docs/guides/function-calling).',
  },
)

export const BetaRankerVersionTypeSchema = t.UnionEnum(['auto', 'default-2024-11-15'], {
  default: undefined,
})

export const BetaHybridSearchOptionsSchema = t.Object({
  embedding_weight: t.Number({
    description: 'The weight of the embedding in the reciprocal ranking fusion.',
  }),
  text_weight: t.Number({
    description: 'The weight of the text in the reciprocal ranking fusion.',
  }),
})

export const BetaRankingOptionsSchema = t.Object({
  ranker: t.Optional(BetaRankerVersionTypeSchema),
  score_threshold: t.Optional(
    t.Number({
      description:
        'The score threshold for the file search, a number between 0 and 1. Numbers closer to 1 will attempt to return only the most relevant results, but may return fewer results.',
    }),
  ),
  hybrid_search: t.Optional(BetaHybridSearchOptionsSchema),
})

export const BetaComparisonFilterSchema = t.Object(
  {
    type: t.UnionEnum(['eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'in', 'nin'], {
      description:
        'Specifies the comparison operator: `eq`, `ne`, `gt`, `gte`, `lt`, `lte`, `in`, `nin`.\n- `eq`: equals\n- `ne`: not equal\n- `gt`: greater than\n- `gte`: greater than or equal\n- `lt`: less than\n- `lte`: less than or equal\n- `in`: in\n- `nin`: not in\n',
      default: 'eq',
    }),
    key: t.String({ description: 'The key to compare against the value.' }),
    value: t.Union(
      [t.String(), t.Number(), t.Boolean(), t.Array(t.Union([t.String(), t.Number()]))],
      {
        description:
          'The value to compare against the attribute key; supports string, number, or boolean types.',
      },
    ),
  },
  {
    additionalProperties: false,
    title: 'Comparison Filter',
    description:
      'A filter used to compare a specified attribute key to a given value using a defined comparison operation.\n',
  },
)

export const BetaCompoundFilterSchema = t.Recursive((Self) =>
  t.Object(
    {
      type: t.UnionEnum(['and', 'or'], {
        description: 'Type of operation: `and` or `or`.',
        default: undefined,
      }),
      filters: t.Array(t.Union([BetaComparisonFilterSchema, Self]), {
        description:
          'Array of filters to combine. Items can be `ComparisonFilter` or `CompoundFilter`.',
      }),
    },
    {
      additionalProperties: false,
      title: 'Compound Filter',
      description: 'Combine multiple filters using `and` or `or`.',
    },
  ),
)

export const BetaFiltersSchema = t.Union([BetaComparisonFilterSchema, BetaCompoundFilterSchema])

export const BetaFileSearchToolSchema = t.Object(
  {
    type: t.Literal('file_search', {
      description: 'The type of the file search tool. Always `file_search`.',
      default: 'file_search',
    }),
    vector_store_ids: t.Array(t.String(), {
      description: 'The IDs of the vector stores to search.',
    }),
    max_num_results: t.Optional(
      t.Integer({
        maximum: 9007199254740991,
        description:
          'The maximum number of results to return. This number should be between 1 and 50 inclusive.',
      }),
    ),
    ranking_options: t.Optional(BetaRankingOptionsSchema),
    filters: t.Optional(t.Union([BetaFiltersSchema, t.Null()])),
  },
  {
    title: 'File search',
    description:
      'A tool that searches for relevant content from uploaded files. Learn more about the [file search tool](https://developers.openai.com/api/docs/guides/tools-file-search).',
  },
)

