export const BetaToolChoiceOptionsSchema = t.UnionEnum(['none', 'auto', 'required'], {
  title: 'Tool choice mode',
  description:
    'Controls which (if any) tool is called by the model.\n\n`none` means the model will not call any tool and instead generates a message.\n\n`auto` means the model can pick between generating a message or calling one or\nmore tools.\n\n`required` means the model must call one or more tools.\n',
  default: undefined,
})

export const BetaToolChoiceAllowedSchema = t.Object(
  {
    type: t.Literal('allowed_tools', {
      description: 'Allowed tool configuration type. Always `allowed_tools`.',
    }),
    mode: t.UnionEnum(['auto', 'required'], {
      description:
        'Constrains the tools available to the model to a pre-defined set.\n\n`auto` allows the model to pick from among the allowed tools and generate a\nmessage.\n\n`required` requires the model to call one or more of the allowed tools.\n',
      default: undefined,
    }),
    tools: t.Array(
      t.Object(
        {},
        { description: 'A tool definition that the model should be allowed to call.\n' },
      ),
      {
        description:
          'A list of tool definitions that the model should be allowed to call.\n\nFor the Responses API, the list of tool definitions might look like:\n```json\n[\n  { "type": "function", "name": "get_weather" },\n  { "type": "mcp", "server_label": "deepwiki" },\n  { "type": "image_generation" }\n]\n```\n',
      },
    ),
  },
  {
    title: 'Allowed tools',
    description: 'Constrains the tools available to the model to a pre-defined set.\n',
  },
)

export const BetaToolChoiceTypesSchema = t.Object(
  {
    type: t.UnionEnum(
      [
        'file_search',
        'web_search_preview',
        'computer',
        'computer_use_preview',
        'computer_use',
        'web_search_preview_2025_03_11',
        'image_generation',
        'code_interpreter',
      ],
      {
        description:
          'The type of hosted tool the model should to use. Learn more about\n[built-in tools](https://developers.openai.com/api/docs/guides/tools).\n\nAllowed values are:\n- `file_search`\n- `web_search_preview`\n- `computer`\n- `computer_use_preview`\n- `computer_use`\n- `code_interpreter`\n- `image_generation`\n',
        default: undefined,
      },
    ),
  },
  {
    title: 'Hosted tool',
    description:
      'Indicates that the model should use a built-in tool to generate a response.\n[Learn more about built-in tools](https://developers.openai.com/api/docs/guides/tools).\n',
  },
)

export const BetaToolChoiceFunctionSchema = t.Object(
  {
    type: t.Literal('function', {
      description: 'For function calling, the type is always `function`.',
    }),
    name: t.String({ description: 'The name of the function to call.' }),
  },
  {
    title: 'Function tool',
    description: 'Use this option to force the model to call a specific function.\n',
  },
)

export const BetaToolChoiceMCPSchema = t.Object(
  {
    type: t.Literal('mcp', { description: 'For MCP tools, the type is always `mcp`.' }),
    server_label: t.String({ description: 'The label of the MCP server to use.\n' }),
    name: t.Optional(
      t.Union([
        t.String({ description: 'The name of the tool to call on the server.\n' }),
        t.Null(),
      ]),
    ),
  },
  {
    title: 'MCP tool',
    description:
      'Use this option to force the model to call a specific tool on a remote MCP server.\n',
  },
)

export const BetaToolChoiceCustomSchema = t.Object(
  {
    type: t.Literal('custom', {
      description: 'For custom tool calling, the type is always `custom`.',
    }),
    name: t.String({ description: 'The name of the custom tool to call.' }),
  },
  {
    title: 'Custom tool',
    description: 'Use this option to force the model to call a specific custom tool.\n',
  },
)

export const BetaSpecificProgrammaticToolCallingParamSchema = t.Object({
  type: t.Literal('programmatic_tool_calling', {
    description: 'The tool to call. Always `programmatic_tool_calling`.',
    default: 'programmatic_tool_calling',
  }),
})

export const BetaSpecificApplyPatchParamSchema = t.Object(
  {
    type: t.Literal('apply_patch', {
      description: 'The tool to call. Always `apply_patch`.',
      default: 'apply_patch',
    }),
  },
  {
    title: 'Specific apply patch tool choice',
    description: 'Forces the model to call the apply_patch tool when executing a tool call.',
  },
)

export const BetaSpecificFunctionShellParamSchema = t.Object(
  {
    type: t.Literal('shell', {
      description: 'The tool to call. Always `shell`.',
      default: 'shell',
    }),
  },
  {
    title: 'Specific shell tool choice',
    description: 'Forces the model to call the shell tool when a tool call is required.',
  },
)

export const BetaToolChoiceParamSchema = t.Union(
  [
    BetaToolChoiceOptionsSchema,
    BetaToolChoiceAllowedSchema,
    BetaToolChoiceTypesSchema,
    BetaToolChoiceFunctionSchema,
    BetaToolChoiceMCPSchema,
    BetaToolChoiceCustomSchema,
    BetaSpecificProgrammaticToolCallingParamSchema,
    BetaSpecificApplyPatchParamSchema,
    BetaSpecificFunctionShellParamSchema,
  ],
  {
    description:
      'How the model should select which tool (or tools) to use when generating\na response. See the `tools` parameter to see how to specify which tools\nthe model can call.\n',
  },
)

export const BetaTokenCountsBodySchema = t.Object({
  model: t.Optional(
    t.Union([
      t.String({
        description:
          'Model ID used to generate the response, like `gpt-4o` or `o3`. OpenAI offers a wide range of models with different capabilities, performance characteristics, and price points. Refer to the [model guide](https://developers.openai.com/api/docs/models) to browse and compare available models.',
      }),
      t.Null(),
    ]),
  ),
  input: t.Optional(
    t.Union([
      t.Union(
        [
          t.String({
            maxLength: 10485760,
            description:
              'A text input to the model, equivalent to a text input with the `user` role.',
          }),
          t.Array(BetaInputItemSchema, {
            maxItems: 131072,
            description:
              'A list of one or many input items to the model, containing different content types.',
          }),
        ],
        { description: 'Text, image, or file inputs to the model, used to generate a response' },
      ),
      t.Null(),
    ]),
  ),
  previous_response_id: t.Optional(
    t.Union([
      t.String({
        example: 'resp_123',
        description:
          'The unique ID of the previous response to the model. Use this to create multi-turn conversations. Learn more about [conversation state](https://developers.openai.com/api/docs/guides/conversation-state). Cannot be used in conjunction with `conversation`.',
      }),
      t.Null(),
    ]),
  ),
  tools: t.Optional(
    t.Union([
      t.Array(BetaToolSchema, {
        description:
          'An array of tools the model may call while generating a response. You can specify which tool to use by setting the `tool_choice` parameter.',
      }),
      t.Null(),
    ]),
  ),
  text: t.Optional(t.Union([BetaResponseTextParamSchema, t.Null()])),
  reasoning: t.Optional(t.Union([BetaReasoningSchema, t.Null()])),
  truncation: t.Optional(BetaTruncationEnumSchema),
  instructions: t.Optional(
    t.Union([
      t.String({
        description:
          "A system (or developer) message inserted into the model's context.\nWhen used along with `previous_response_id`, the instructions from a previous response will not be carried over to the next response. This makes it simple to swap out system (or developer) messages in new responses.",
      }),
      t.Null(),
    ]),
  ),
  personality: t.Optional(BetaPersonalityEnumSchema),
  conversation: t.Optional(t.Union([BetaConversationParamSchema, t.Null()])),
  tool_choice: t.Optional(t.Union([BetaToolChoiceParamSchema, t.Null()])),
  parallel_tool_calls: t.Optional(
    t.Union([
      t.Boolean({ description: 'Whether to allow the model to run tool calls in parallel.' }),
      t.Null(),
    ]),
  ),
})

