export const BetaResponseInjectCreatedEventSchema = t.Object(
  {
    type: t.Literal('response.inject.created', {
      description: 'The event discriminator. Always `response.inject.created`.',
    }),
    response_id: t.String({ description: 'The ID of the response that accepted the input.' }),
    sequence_number: t.Integer({
      maximum: 9007199254740991,
      description: 'The sequence number for this event.',
    }),
    stream_id: t.Optional(
      t.String({
        description:
          'The multiplexed WebSocket stream that emitted the event. This field is\npresent only when WebSocket multiplexing is enabled separately.\n',
      }),
    ),
  },
  {
    title: 'ResponseInjectCreatedEvent',
    description:
      'Emitted when all injected input items were validated and committed to the\nactive response.\n',
  },
)

export const BetaResponseInjectFailedEventSchema = t.Object(
  {
    type: t.Literal('response.inject.failed', {
      description: 'The event discriminator. Always `response.inject.failed`.',
    }),
    response_id: t.String({ description: 'The ID of the response that rejected the input.' }),
    input: t.Array(BetaInputItemSchema, {
      description: 'The raw input items that were not committed.',
    }),
    error: t.Object(
      {
        code: t.UnionEnum(['response_already_completed', 'response_not_found'], {
          description: 'A machine-readable error code.',
          default: undefined,
        }),
        message: t.String({ description: 'A human-readable description of the error.' }),
      },
      { description: 'Information about why the input was not committed.' },
    ),
    sequence_number: t.Integer({
      maximum: 9007199254740991,
      description: 'The sequence number for this event.',
    }),
    stream_id: t.Optional(
      t.String({
        description:
          'The multiplexed WebSocket stream that emitted the event. This field is\npresent only when WebSocket multiplexing is enabled separately.\n',
      }),
    ),
  },
  {
    title: 'ResponseInjectFailedEvent',
    description:
      'Emitted when injected input could not be committed to a response. The event\nreturns the uncommitted raw input so the client can retry it in another\nresponse when appropriate.\n',
  },
)

